// Verifiable periodic mipmap chains with per-level filtering error.
// Semantics per channel family:
//   color  (albedo RGB, roughness/anisotropy/coverage scalars): box average
//   vector (normal RGB, flow XY): average then re-normalize (linear averaging of
//           unit vectors, never averaging encoded bytes as if they were colors)
// Every level is generated by 2x2 box filtering the previous level with wrapped
// indices, which exactly matches GL_LINEAR_MIPMAP_LINEAR over a periodic tile.

import { wrap } from './math-util.js';
import { footprintFromCoverage, lodFromFootprint } from './sampling-spec.js';

function boxAverageScalars(src, srcSize, dstSize, pixelSize) {
  const dst = new Uint8ClampedArray(dstSize * dstSize * pixelSize);
  for (let y = 0; y < dstSize; y++) {
    for (let x = 0; x < dstSize; x++) {
      const sx = x * 2;
      const sy = y * 2;
      for (let c = 0; c < pixelSize; c++) {
        let acc = 0;
        for (let dy = 0; dy < 2; dy++) {
          for (let dx = 0; dx < 2; dx++) {
            acc += src[((wrap(sy + dy, srcSize)) * srcSize + wrap(sx + dx, srcSize)) * pixelSize + c];
          }
        }
        dst[(y * dstSize + x) * pixelSize + c] = acc / 4;
      }
    }
  }
  return dst;
}

function boxAverageVectors(src, srcSize, dstSize, channelCount) {
  // Decode -> linear average -> re-normalize -> re-encode.
  const dst = new Uint8ClampedArray(dstSize * dstSize * 4);
  for (let y = 0; y < dstSize; y++) {
    for (let x = 0; x < dstSize; x++) {
      const sx = x * 2;
      const sy = y * 2;
      let ax = 0, ay = 0, az = 0, aa = 0;
      for (let dy = 0; dy < 2; dy++) {
        for (let dx = 0; dx < 2; dx++) {
          const i = (wrap(sy + dy, srcSize) * srcSize + wrap(sx + dx, srcSize)) * 4;
          ax += src[i] / 255 * 2 - 1;
          ay += src[i + 1] / 255 * 2 - 1;
          az += channelCount === 3 ? src[i + 2] / 255 * 2 - 1 : 0;
          aa += src[i + 3];
        }
      }
      ax /= 4; ay /= 4; az /= 4; aa /= 4;
      const len = Math.hypot(ax, ay, az);
      if (len > 1e-6) { ax /= len; ay /= len; az /= len; }
      else { ax = 0; ay = 0; az = 1; }
      const o = (y * dstSize + x) * 4;
      dst[o] = (ax * 0.5 + 0.5) * 255;
      dst[o + 1] = (ay * 0.5 + 0.5) * 255;
      dst[o + 2] = (az * 0.5 + 0.5) * 255;
      dst[o + 3] = aa; // scalar alpha channel keeps box-average semantics
    }
  }
  return dst;
}

export function buildMipChain(level0, baseSize, kind /* 'scalar' | 'normal3' | 'vector2' */) {
  const levels = [{ size: baseSize, data: level0 }];
  let size = baseSize;
  let data = level0;
  while (size > 1) {
    const dstSize = size / 2;
    const dst = kind === 'scalar'
      ? boxAverageScalars(data, size, dstSize, 4)
      : boxAverageVectors(data, size, dstSize, kind === 'normal3' ? 3 : 2);
    levels.push({ size: dstSize, data: dst });
    size = dstSize;
    data = dst;
  }
  return levels;
}

// RMSE between a coarse level (upsampled by nearest) and the base level, in
// encoded-byte units. This is the *filtering residual* the UI shows alongside
// the rendered cloth, proving distant views use filtered data rather than a
// contrast hack. For vector maps the error is measured on decoded unit vectors.
export function levelErrorAgainstBase(chain, kind) {
  const base = chain[0].data;
  const baseSize = chain[0].size;
  return chain.slice(1).map((lvl) => {
    let se = 0;
    let n = 0;
    const channels = kind === 'scalar' ? 3 : (kind === 'normal3' ? 3 : 2);
    for (let y = 0; y < baseSize; y++) {
      for (let x = 0; x < baseSize; x++) {
        const cx = Math.min(lvl.size - 1, Math.floor(x / lvl.size));
        const cy = Math.min(lvl.size - 1, Math.floor(y / lvl.size));
        const bi = (y * baseSize + x) * 4;
        const ci = (cy * lvl.size + cx) * 4;
        for (let c = 0; c < channels; c++) {
          let diff;
          if (kind === 'scalar') {
            diff = (base[bi + c] - lvl.data[ci + c]) / 255;
          } else {
            const b = base[bi + c] / 255 * 2 - 1;
            const q = lvl.data[ci + c] / 255 * 2 - 1;
            diff = (b - q) * 0.5; // map [-2,2] back to byte-like scale
          }
          se += diff * diff;
          n++;
        }
      }
    }
    return { level: chain.indexOf(lvl), size: lvl.size, rmse: Math.sqrt(se / n) };
  });
}

// Screen-coverage LOD selection. `tileTexels` is how many DEVICE pixels one
// texture tile covers on screen.
//
// Compatibility adapter only: the reciprocal coverage formula lives in
// sampling-spec.js so the CLI, the HUD and the shader all select levels from
// the same footprint definition. Zero bias, because the CLI has no UI LOD bias.
export function selectLod(chain, tileTexels) {
  const baseSize = chain[0].size;
  const foot = footprintFromCoverage(tileTexels, baseSize);
  return lodFromFootprint(foot, 0, chain.length);
}
